// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 d, uint256 w, uint256 e) public {
        vm.assume(d <= VALUE_CAP);
        vm.assume(e <= VALUE_CAP);
        d = bound(d, 1, 1000 ether);
        w = bound(w, 1, d);
        e = bound(e, 1, 1000 ether);

        address a = address(0xA11ce);
        address b = address(0xB0b);

        // a deposits d
        vm.deal(a, d);
        vm.prank(a);
        c.deposit{value: d}();

        // b deposits e (another user's funds)
        vm.deal(b, e);
        vm.prank(b);
        c.deposit{value: e}();

        // a withdraws w (admissible: w <= recorded balance d, and contract holds d+e >= w)
        vm.prank(a);
        c.withdraw(w);

        // Rule: a's recorded balance is now d-w, so withdrawing the full original deposit d must fail.
        bool ok;
        vm.prank(a);
        try c.withdraw(d) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "withdrawing full original deposit after partial withdrawal must fail");
    }
}
